css:
.forgesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7edf2;
    background: linear-gradient(160deg, #11161c 0%, #1a232d 60%, #141b22 100%);
    border-radius: 18px;
}

.forgesim-container * {
    box-sizing: border-box;
}

.forgesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0d1318 0%, #233241 55%, #2c4055 100%);
    color: #f4f7fa;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #34485c;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}

.forgesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffb347;
    text-shadow: 0 1px 0 rgba(0, 0, 0, 0.4);
}

.forgesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffce8a;
    background: rgba(255, 179, 71, 0.12);
    border: 1px solid rgba(255, 179, 71, 0.30);
    padding: 5px 14px;
    border-radius: 999px;
}

.forgesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c4d0db;
}

.forgesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb2c2;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.forgesim-period-counter #currentDay,
.forgesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #ffb347;
}

.forgesim-round-name {
    background: #2a3a4a;
    color: #ffce8a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid #3a4f63;
}

.forgesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9d7a;
    background: rgba(192, 57, 43, 0.18);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(192, 57, 43, 0.35);
}

.forgesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.forgesim-status-card {
    background: #1c2530;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #2e3e4f;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.30);
    border-top: 4px solid #5a7184;
}

.forgesim-card-defect { border-top-color: #c0392b; }
.forgesim-card-coq { border-top-color: #d98a16; }
.forgesim-card-delivery { border-top-color: #2f86b0; }
.forgesim-card-pipeline { border-top-color: #6aa84f; }

.forgesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8499a9;
}

.forgesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f4f7fa;
}

.forgesim-card-defect .forgesim-value { color: #e8705f; }
.forgesim-card-coq .forgesim-value { color: #f0ad4e; }
.forgesim-card-delivery .forgesim-value { color: #54a8d4; }
.forgesim-card-pipeline .forgesim-value { color: #8ec96e; }

.forgesim-sublabel {
    font-size: 0.76rem;
    color: #7f93a3;
    line-height: 1.35;
}

.forgesim-defect-pass .forgesim-value { color: #8ec96e; }
.forgesim-defect-fail .forgesim-value { color: #e8705f; }

.forgesim-budget-over { border-top-color: #c0392b; }
.forgesim-budget-over .forgesim-value { color: #e8705f; }

.forgesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f1620;
    color: #ffce8a;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #2e3e4f;
}

.forgesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffb347;
}

.forgesim-budget-bar.forgesim-budget-breach {
    border-color: #c0392b;
}

.forgesim-budget-bar.forgesim-budget-breach #budgetDisplay {
    color: #e8705f;
}

.forgesim-briefing {
    display: flex;
    gap: 14px;
    background: #1c2530;
    border-left: 5px solid #ffb347;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #2e3e4f;
    border-left-width: 5px;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.forgesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.forgesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffb347;
    margin-bottom: 6px;
}

.forgesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c4d0db;
}

.forgesim-briefing-text strong { color: #8ec96e; }
.forgesim-briefing-text em { color: #ff9d7a; font-style: italic; }

.forgesim-controls {
    background: #1c2530;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #2e3e4f;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.30);
}

.forgesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f4f7fa;
    border-bottom: 2px solid #2e3e4f;
    padding-bottom: 8px;
}

.forgesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #d3dee7;
    margin: 14px 0 6px;
}

.forgesim-container select,
.forgesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #3a4f63;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #131b24;
    color: #e7edf2;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.forgesim-container select:focus,
.forgesim-container input[type="number"]:focus {
    outline: none;
    border-color: #ffb347;
    box-shadow: 0 0 0 3px rgba(255, 179, 71, 0.18);
}

.forgesim-container select option {
    background-color: #131b24;
    color: #e7edf2;
}

.forgesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #ffb347;
}

.forgesim-range-readout,
.forgesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb2c2;
    margin-top: 4px;
}

.forgesim-range-readout span:last-child,
.forgesim-alloc-readout span:nth-child(2) {
    color: #ffb347;
    font-weight: 800;
}

.forgesim-hint {
    font-size: 0.8rem;
    color: #7f93a3;
    margin-top: 4px;
    line-height: 1.4;
}

.forgesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.forgesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #131b24;
    border: 1px solid #2e3e4f;
    border-radius: 9px;
    padding: 8px 12px;
}

.forgesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #c4d0db;
}

.forgesim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.forgesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.forgesim-container .btn-primary {
    background: linear-gradient(135deg, #d98a16 0%, #ffb347 100%);
    border: none;
    color: #1a1206;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(217, 138, 22, 0.32);
}

.forgesim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.forgesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #3a4f63;
    color: #9fb2c2;
    background: transparent;
}

.forgesim-coach {
    background: #0f1620;
    color: #d3dee7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #2e3e4f;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.forgesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffb347;
    margin-bottom: 8px;
}

.forgesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.forgesim-coach-body strong { color: #ffce8a; }
.forgesim-coach-body em { color: #ff9d7a; font-style: italic; }

.forgesim-history,
.forgesim-chart {
    background: #1c2530;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #2e3e4f;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.30);
}

.forgesim-history h3,
.forgesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f4f7fa;
}

.forgesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d0db;
}

.forgesim-container table#usfHistoryTable th {
    background: #131b24;
    color: #ffb347;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2e3e4f;
}

.forgesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #26323e;
    color: #c4d0db;
}

.forgesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #19222c;
}

.forgesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .forgesim-container {
        padding: 14px;
    }
    .forgesim-header h1 {
        font-size: 1.7rem;
    }
    .forgesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .forgesim-value {
        font-size: 2rem;
    }
    .forgesim-clock {
        margin-left: 0;
    }
    .forgesim-period-counter {
        font-size: 0.88rem;
    }
    .forgesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .forgesim-alloc-row {
        flex-wrap: wrap;
    }
    .forgesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .forgesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained, forge palette) */
.forgesim-cm { background:#f4f7fa; color:#131b24; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(28,37,48,0.2); }
.forgesim-cm-head { text-align:center; border-bottom:1px solid #c4d0db; padding-bottom:14px; margin-bottom:16px; }
.forgesim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5a6b7a; font-weight:700; }
.forgesim-cm-scorewrap { margin:8px 0 2px; }
.forgesim-cm-score { font-size:52px; font-weight:800; color:#2e3e4f; line-height:1; }
.forgesim-cm-score-max { font-size:20px; color:#8496a4; font-weight:600; }
.forgesim-cm-grade { font-size:19px; font-weight:700; color:#131b24; margin-top:4px; }
.forgesim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.forgesim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.forgesim-cm-met { background:#ffe4bd; color:#8a5a12; }
.forgesim-cm-fail { background:#f6d9d3; color:#9c3a2b; }
.forgesim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.forgesim-cm-metric { background:#e6edf3; border-radius:10px; padding:12px 16px; min-width:100px; text-align:center; }
.forgesim-cm-metric-val { font-size:22px; font-weight:800; color:#2e3e4f; }
.forgesim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5a6b7a; margin-top:3px; }
.forgesim-cm-insights { background:#e6edf3; border-radius:10px; padding:14px 18px; }
.forgesim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5a6b7a; font-weight:700; margin-bottom:8px; }
.forgesim-cm-insights ul { margin:0; padding-left:18px; }
.forgesim-cm-insights li { font-size:14px; line-height:1.5; color:#2b3844; margin-bottom:7px; }

