(function() {
    'use strict';

    class ForgeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Forum for Innovation`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Esmaltec Sul S.A., BRL).
            this.START_DEFECT = 4.2;        // %
            this.TARGET_DEFECT = 2.0;       // CasaForte ultimatum
            this.BESTINCLASS_DEFECT = 1.5;  // industry best
            this.PLATEAU_DEFECT = 2.5;      // floor if the process root cause is NOT fixed (concept: ~2.8% plateau, above the 2.0% target)
            this.START_COQ = 9.0;           // % of revenue (R$64.8M)
            this.BESTPRACTICE_COQ = 5.0;    // recovers ~R$28.8M
            this.START_DELIVERY = 70;       // peak-season volume protected (0-100)
            this.START_PIPELINE = 25;       // innovation pipeline value (0-100)
            this.BUDGET_CAP = 22;           // R$22M board envelope (in millions)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    defect: this.START_DEFECT,
                    coq: this.START_COQ,
                    delivery: this.START_DELIVERY,
                    pipeline: this.START_PIPELINE,
                    budgetUsed: 0,
                    budgetBreach: false,
                    targetMissed: false,
                    metricGamed: false,
                    processFixed: false,
                    defectHistory: [this.START_DEFECT],
                    coqHistory: [this.START_COQ],
                    deliveryHistory: [this.START_DELIVERY],
                    pipelineHistory: [this.START_PIPELINE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed a MIDDLING / neutral set — never the textbook-correct play.
                state.decisions = {
                    root: `execution`,
                    coqFrame: `expense`,
                    rigor: 55,
                    project: `c_only`,
                    capex: 14,
                    reframe: 50,
                    scorecard: `defectonly`,
                    casaforte: 55,
                    other: 30,
                    control: 15,
                    reinspect: 30,
                    sequence: `alllines`,
                    bridge: `nothing`,
                    trial: `push`,
                    pitch: 65
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const cf = document.getElementById(`coqFrameInput`);
                const rg = document.getElementById(`rigorInput`);
                if (root) decisions.root = root.value;
                if (cf) decisions.coqFrame = cf.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const pr = document.getElementById(`projectInput`);
                const cx = document.getElementById(`capexInput`);
                const rf = document.getElementById(`reframeInput`);
                if (pr) decisions.project = pr.value;
                if (cx) decisions.capex = parseFloat(cx.value);
                if (rf) decisions.reframe = parseInt(rf.value, 10);
                if (!Number.isFinite(decisions.capex) || decisions.capex < 0) {
                    warn(`warn_capex_negative`); return false;
                }
                if (decisions.capex > this.BUDGET_CAP + 0.001) {
                    warn(`warn_capex_cap`); return false;
                }
                if (!Number.isFinite(decisions.reframe) || decisions.reframe < 0 || decisions.reframe > 100) {
                    warn(`warn_reframe_range`); return false;
                }
            } else if (round === 3) {
                const sc = document.getElementById(`scorecardInput`);
                const cf = document.getElementById(`casaforteInput`);
                const ot = document.getElementById(`otherInput`);
                const ct = document.getElementById(`controlInput`);
                const ri = document.getElementById(`reinspectInput`);
                if (sc) decisions.scorecard = sc.value;
                if (cf) decisions.casaforte = parseFloat(cf.value);
                if (ot) decisions.other = parseFloat(ot.value);
                if (ct) decisions.control = parseFloat(ct.value);
                if (ri) decisions.reinspect = parseInt(ri.value, 10);
                const parts = [decisions.casaforte, decisions.other, decisions.control];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.casaforte + decisions.other + decisions.control);
                if (total !== 100) {
                    warn(`warn_alloc_total`); return false;
                }
                if (!Number.isFinite(decisions.reinspect) || decisions.reinspect < 0 || decisions.reinspect > 100) {
                    warn(`warn_reinspect_range`); return false;
                }
            } else if (round === 4) {
                const sq = document.getElementById(`sequenceInput`);
                const br = document.getElementById(`bridgeInput`);
                const tr = document.getElementById(`trialInput`);
                const pi = document.getElementById(`pitchInput`);
                if (sq) decisions.sequence = sq.value;
                if (br) decisions.bridge = br.value;
                if (tr) decisions.trial = tr.value;
                if (pi) decisions.pitch = parseInt(pi.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. defect/coq DOWN is good (negative delta = improvement).
            // delivery/pipeline 0-100. spend in R$ millions.
            let defectDelta = 0, coqDelta = 0, deliveryDelta = 0, pipelineDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: ~60% of defects are the aging process itself (process limitation).
                // Matching the intervention to the root cause is the lesson.
                if (d.root === `process`) {
                    pipelineDelta += 8; coachKey = `coach_r1_process`;
                } else if (d.root === `execution`) {
                    pipelineDelta -= 4; coachKey = `coach_r1_execution`;
                } else if (d.root === `people`) {
                    pipelineDelta -= 8; defectDelta += 0.1; coachKey = `coach_r1_people`;
                } else {
                    pipelineDelta -= 10; coachKey = `coach_r1_random`;
                }

                // Cost-of-quality framing: investment vs expense (Common Error 5).
                if (d.coqFrame === `investment`) {
                    coqDelta -= 0.4; pipelineDelta += 6;
                    if (d.root === `process`) coachKey = `coach_r1_sharp`;
                } else if (d.coqFrame === `expense`) {
                    pipelineDelta -= 4; coachKey = (coachKey === `coach_r1_process`) ? `coach_r1_expense` : coachKey;
                } else {
                    coqDelta += 0.3; pipelineDelta -= 6; coachKey = `coach_r1_ignore`;
                }

                // Diagnostic rigor sharpens every later decision.
                if (d.rigor >= 70) { pipelineDelta += 6; coqDelta -= 0.2; }
                else if (d.rigor <= 30) { pipelineDelta -= 6; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.root === `process` && d.coqFrame === `investment`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the project inside R$22M. A fixes the root cause; B chases revenue
                // and raises near-term defect risk; C plateaus ~2.8%; thin spreading reaches none.
                spend = d.capex;
                const funded = d.capex >= 17;        // enough for the major project + improvement
                const starved = d.capex < 12;        // under critical mass

                // Only the process innovation A (alone or with C), funded to critical mass,
                // actually replaces the aging enamel-application process — the ~60% root cause.
                // Any other choice (or an A install starved of capital) can tighten variation but
                // NOT fix the process, so it plateaus above the 2.0% target (concept: continuous
                // improvement ~2.8%; product B raises near-term risk; thin spreading reaches none).
                ds.processFixed = (d.project === `a_plus_c` || d.project === `a_only`) && funded;

                switch (d.project) {
                    case `a_plus_c`:
                        // The concept-correct play: process A (root-cause fix) + SPC to lock gains.
                        defectDelta -= funded ? 1.3 : (starved ? 0.4 : 0.9);
                        coqDelta -= funded ? 1.2 : 0.6;
                        pipelineDelta += funded ? 16 : 8;
                        deliveryDelta -= 6; // install will consume line-time (handled R4)
                        coachKey = funded ? `coach_r2_apc` : `coach_r2_starved`;
                        break;
                    case `a_only`:
                        defectDelta -= funded ? 1.1 : 0.5;
                        coqDelta -= funded ? 0.9 : 0.4;
                        pipelineDelta += funded ? 12 : 6;
                        deliveryDelta -= 6;
                        coachKey = `coach_r2_aonly`;
                        break;
                    case `b_plus_c`:
                        // Product innovation while CasaForte is on notice — defects tick UP.
                        defectDelta += 0.4; // raises near-term defect risk on watched lines
                        coqDelta += 0.3;
                        pipelineDelta += 14; // strong revenue/pipeline upside
                        deliveryDelta -= 2;
                        coachKey = `coach_r2_bpc`;
                        break;
                    case `c_only`:
                        // Cheap, fast, low-downtime — but plateaus; cannot fix the process root cause.
                        defectDelta -= 0.7; // bounded improvement
                        coqDelta -= 0.4;
                        pipelineDelta += 4;
                        deliveryDelta += 2; // low downtime protects delivery
                        coachKey = `coach_r2_conly`;
                        break;
                    case `all_thin`:
                        // None reaches critical mass (Common Error 3: thin spreading).
                        defectDelta -= 0.3;
                        coqDelta -= 0.1;
                        pipelineDelta += 5;
                        deliveryDelta -= 3;
                        coachKey = `coach_r2_thin`;
                        break;
                }

                // Funding discipline: starving the chosen project undercuts it; breaching the cap
                // is flagged and penalized.
                if (starved && (d.project === `a_plus_c` || d.project === `a_only`)) {
                    pipelineDelta -= 4; coachKey = `coach_r2_starved`;
                }

                // Reframe conviction unlocks the cost-of-quality recovery (links to R1 framing).
                if (d.reframe >= 65) { coqDelta -= 0.4; pipelineDelta += 3; }
                else if (d.reframe <= 30) { coqDelta += 0.2; }

                summaryKey = (d.project === `a_plus_c` && funded) ? `sum_r2_good` : (d.project === `b_plus_c` ? `sum_r2_revenue` : (d.project === `all_thin` ? `sum_r2_thin` : `sum_r2_weak`));
            } else if (round === 3) {
                // Set the scorecard & allocate. A balanced scorecard beats single-metric tunnel
                // vision; manual re-inspection is a trap that inflates cycle time & cost of quality.
                switch (d.scorecard) {
                    case `balanced`:
                        defectDelta -= 0.6; coqDelta -= 0.6; pipelineDelta += 4; coachKey = `coach_r3_balanced`; break;
                    case `defectonly`:
                        defectDelta -= 0.5; coqDelta += 0.3; coachKey = `coach_r3_defectonly`; break;
                    case `output`:
                        defectDelta += 0.2; coqDelta += 0.2; deliveryDelta += 3; coachKey = `coach_r3_output`; break;
                }

                // Allocation: concentrate on CasaForte lines without neglecting the others or
                // skipping the SPC control phase.
                const cf = d.casaforte, ot = d.other, ct = d.control;
                if (cf >= 45 && cf <= 65 && ot >= 20 && ct >= 10) {
                    defectDelta -= 0.5; deliveryDelta += 4; coqDelta -= 0.2;
                    coachKey = (d.scorecard === `balanced`) ? `coach_r3_allocgood` : coachKey;
                } else if (cf > 75) {
                    defectDelta -= 0.3; deliveryDelta -= 5; // CasaForte fixed, others neglected
                    coachKey = `coach_r3_overconcentrate`;
                } else if (ct < 10) {
                    defectDelta -= 0.1; pipelineDelta -= 3; // no control phase → gains backslide
                    coachKey = `coach_r3_nocontrol`;
                } else {
                    defectDelta -= 0.2; deliveryDelta += 1;
                }

                // Manual re-inspection: forces the headline number but inflates cycle time & COQ
                // (Common Error 4: single-metric gaming).
                if (d.reinspect >= 60) {
                    defectDelta -= 0.4; coqDelta += 1.4; deliveryDelta -= 6; ds.metricGamed = true;
                    coachKey = `coach_r3_reinspect`;
                } else if (d.reinspect >= 35) {
                    defectDelta -= 0.2; coqDelta += 0.5; deliveryDelta -= 2;
                } else {
                    coqDelta -= 0.1;
                }

                summaryKey = (d.scorecard === `balanced` && d.reinspect < 35) ? `sum_r3_good` : (ds.metricGamed ? `sum_r3_gamed` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recover & commit: protect delivery while the install runs, handle the failed trial.
                switch (d.sequence) {
                    case `phased`:
                        deliveryDelta += 12; defectDelta -= 0.3; coachKey = `coach_r4_phased`; break;
                    case `alllines`:
                        deliveryDelta -= 14; defectDelta -= 0.4; coachKey = `coach_r4_alllines`; break;
                    case `delay`:
                        deliveryDelta += 6; defectDelta += 0.6; ds.targetMissed = true; coachKey = `coach_r4_delay`; break;
                }

                // Bridge the ~180,000 lost units.
                switch (d.bridge) {
                    case `mixed`:
                        deliveryDelta += 12; coqDelta += 0.3; coachKey = (d.sequence === `phased`) ? `coach_r4_bridgegood` : coachKey; break;
                    case `nothing`:
                        deliveryDelta -= 14; coachKey = `coach_r4_bridgenothing`; break;
                    case `renegotiate`:
                        deliveryDelta += 6; defectDelta += 0.2; coachKey = `coach_r4_renegotiate`; break;
                }

                // The mid-project trial underperforms — adjust, push, or fall back.
                switch (d.trial) {
                    case `adjust`:
                        defectDelta -= 0.5; pipelineDelta += 6; coqDelta -= 0.3; coachKey = (d.sequence === `phased` && d.bridge === `mixed`) ? `coach_r4_strong` : coachKey; break;
                    case `push`:
                        defectDelta += 0.5; coqDelta += 0.6; deliveryDelta -= 4; coachKey = `coach_r4_push`; break;
                    case `fallback`:
                        defectDelta += 0.4; pipelineDelta -= 8; coachKey = `coach_r4_fallback`; break;
                }

                // Board-pitch conviction nudges pipeline credibility.
                pipelineDelta += Math.round((d.pitch - 60) / 8);

                summaryKey = (d.sequence === `phased` && d.bridge === `mixed` && d.trial === `adjust`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Budget accounting (cumulative; spend only committed in R2).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) ds.budgetBreach = true;

            // Apply deltas with floors/ceilings. The defect floor depends on whether the
            // PROCESS root cause was actually fixed: only process innovation A (funded to
            // critical mass) can reach best-in-class 1.5%. Without it, the aging process caps
            // improvement at a plateau ABOVE the 2.0% CasaForte target — no amount of scorecard,
            // allocation or sequencing in R3/R4 can clear the target if the root cause is unfixed.
            // This enforces the concept's central lesson (match the intervention to the root cause;
            // continuous improvement alone plateaus ~2.8%, short of 2.0%).
            const defectFloor = ds.processFixed ? this.BESTINCLASS_DEFECT : this.PLATEAU_DEFECT;
            ds.defect = Math.max(defectFloor, Math.round((ds.defect + defectDelta) * 100) / 100);
            ds.coq = Math.max(3.5, Math.round((ds.coq + coqDelta) * 100) / 100);
            ds.delivery = Math.max(0, Math.min(100, ds.delivery + deliveryDelta));
            ds.pipeline = Math.max(0, Math.min(100, ds.pipeline + pipelineDelta));

            ds.defectHistory.push(Math.round(ds.defect * 100) / 100);
            ds.coqHistory.push(Math.round(ds.coq * 10) / 10);
            ds.deliveryHistory.push(Math.round(ds.delivery));
            ds.pipelineHistory.push(Math.round(ds.pipeline));

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            if (round === this.ROUNDS.length && ds.defect > this.TARGET_DEFECT) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                defect: Math.round(ds.defect * 100) / 100,
                defectDelta: Math.round(defectDelta * 100) / 100,
                coq: Math.round(ds.coq * 10) / 10,
                coqDelta: Math.round(coqDelta * 10) / 10,
                delivery: Math.round(ds.delivery),
                deliveryDelta: Math.round(deliveryDelta),
                pipeline: Math.round(ds.pipeline),
                pipelineDelta: Math.round(pipelineDelta),
                budgetUsed: ds.budgetUsed,
                budgetBreach: ds.budgetBreach,
                metricGamed: ds.metricGamed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
