                    card.classList.toggle(`forgesim-defect-fail`, Number(v) >= this.TARGET_DEFECT);
                }
                return (Math.round(Number(v) * 100) / 100).toFixed(1) + `%`;
            });
            uiManager.bind(`coqDisplay`, `domainState.coq`, (v) => (Math.round(Number(v) * 10) / 10).toFixed(1) + `%`);
            uiManager.bind(`deliveryDisplay`, `domainState.delivery`, (v) => Math.round(v));
            uiManager.bind(`pipelineDisplay`, `domainState.pipeline`, (v) => Math.round(v));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.forgesim-budget-bar`);
                if (bar) bar.classList.toggle(`forgesim-budget-breach`, Number(v) > this.BUDGET_CAP + 0.001);
                return `R$` + (Math.round(Number(v) * 10) / 10) + ` mi / R$22 mi`;
            });

            const self = this;

            // Rigor slider readout.
            this._bindSlider(`rigorInput`, `rigorReadout`);
            // Reframe slider readout.
            this._bindSlider(`reframeInput`, `reframeReadout`);
            // Re-inspection slider readout.
            this._bindSlider(`reinspectInput`, `reinspectReadout`);

            // Effort-allocation live total (must equal 100%).
            const allocIds = [`casaforteInput`, `otherInput`, `controlInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.forgesim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#e8705f` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

