        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.defectHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                forgeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.defectHistory },
                        { data: ds.coqHistory },
                        { data: ds.deliveryHistory },
                        { data: ds.pipelineHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const defect = Math.round(ds.defect * 100) / 100;
            const coq = Math.round(ds.coq * 10) / 10;
            const delivery = Math.round(ds.delivery);
            const pipeline = Math.round(ds.pipeline);
            const defectScore = Math.max(0, Math.min(100, (this.START_DEFECT - defect) / (this.START_DEFECT - this.BESTINCLASS_DEFECT) * 100));
            const coqScore = Math.max(0, Math.min(100, (this.START_COQ - coq) / (this.START_COQ - this.BESTPRACTICE_COQ) * 100));
            return Math.round(defectScore * 0.35 + coqScore * 0.20 + delivery * 0.25 + pipeline * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const defect = Math.round(ds.defect * 100) / 100;
            const coq = Math.round(ds.coq * 10) / 10;
            const delivery = Math.round(ds.delivery);
            const pipeline = Math.round(ds.pipeline);

            const hitTarget = defect < this.TARGET_DEFECT;
            const protectedDelivery = delivery >= 60;
            const recoveredCoq = coq <= this.BESTPRACTICE_COQ + 1.0;
            const gamed = ds.metricGamed || (hitTarget && coq > this.START_COQ);
            const breach = ds.budgetBreach;

            const composite = this._composite(ds);

            let performanceKey = `grade_stuck`;
            if (hitTarget && protectedDelivery && recoveredCoq && composite >= 70 && !breach) performanceKey = `grade_won`;
            else if (hitTarget && protectedDelivery && !breach) performanceKey = `grade_credible`;
            else if (hitTarget && gamed) performanceKey = `grade_gamed`;
            else if (hitTarget && !protectedDelivery) performanceKey = `grade_delivery`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (defect <= this.START_DEFECT - 1.0) performanceKey = `grade_improving`;
            const performance = window.mySimulation.t(performanceKey);
            const met = hitTarget && protectedDelivery && recoveredCoq && composite >= 70 && !breach;

            const insights = [];
            if (hitTarget && protectedDelivery && recoveredCoq) insights.push(window.mySimulation.t(`insight_won`));
            else if (hitTarget && gamed) insights.push(window.mySimulation.t(`insight_gamed`));
            else if (hitTarget && !protectedDelivery) insights.push(window.mySimulation.t(`insight_delivery`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (breach) insights.push(window.mySimulation.t(`insight_breach`));
            if (coq > this.START_COQ) insights.push(window.mySimulation.t(`insight_coqup`));
            if (pipeline < 30) insights.push(window.mySimulation.t(`insight_lowpipe`));
            if (defect <= this.BESTINCLASS_DEFECT + 0.05) insights.push(window.mySimulation.t(`insight_bestinclass`));
            if (hitTarget && protectedDelivery && recoveredCoq && composite >= 70 && !breach) insights.push(window.mySimulation.t(`insight_balanced`));

            return {
                defect: defect,
                coq: coq,
                delivery: delivery,
                pipeline: pipeline,
                hitTarget: hitTarget,
                gamed: gamed,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                protectedDelivery: protectedDelivery,
                breach: breach,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="forgesim-cm-badge ` + (s.met ? `forgesim-cm-met` : `forgesim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.protectedDelivery === false) badges.push(`<span class="forgesim-cm-badge forgesim-cm-fail">` + t(`cm_fail_delivery`) + `</span>`);
            if (s.breach) badges.push(`<span class="forgesim-cm-badge forgesim-cm-fail">` + t(`cm_fail_breach`) + `</span>`);
            if (s.gamed) badges.push(`<span class="forgesim-cm-badge forgesim-cm-fail">` + t(`cm_fail_gamed`) + `</span>`);
            const kpi = (label, val) => `<div class="forgesim-cm-metric"><div class="forgesim-cm-metric-val">` + val + `</div><div class="forgesim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_defect`), (s.defect != null ? s.defect : 0) + `%`)
                + kpi(t(`cm_coq`), (s.coq != null ? s.coq : 0) + `%`)
                + kpi(t(`cm_delivery`), (s.delivery != null ? Math.round(s.delivery) : 0))
                + kpi(t(`cm_pipeline`), (s.pipeline != null ? Math.round(s.pipeline) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="forgesim-cm">`
                + `<div class="forgesim-cm-head"><div class="forgesim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="forgesim-cm-scorewrap"><span class="forgesim-cm-score">` + score + `</span><span class="forgesim-cm-score-max">/100</span></div>`
                + `<div class="forgesim-cm-grade">` + grade + `</div>`
                + `<div class="forgesim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="forgesim-cm-metrics">` + kpis + `</div>`
                + `<div class="forgesim-cm-insights"><div class="forgesim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
